package com.smritisathi.app.core;
import android.content.*;import android.database.sqlite.*;import android.content.ContentValues;import java.util.*;
public class OfflineDb extends SQLiteOpenHelper {static final String DB="smriti_sathi_local.db";public OfflineDb(Context c){super(c,DB,null,1);}public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE sessions(id INTEGER PRIMARY KEY AUTOINCREMENT,patientId TEXT,gameType TEXT,difficulty TEXT,score INTEGER,accuracy INTEGER,reactionTimeMs INTEGER,durationSeconds INTEGER,createdAt INTEGER,synced INTEGER DEFAULT 0)");}public void onUpgrade(SQLiteDatabase d,int a,int b){}public static void save(Context c,String p,String type,int score,int acc,long rt,int dur){OfflineDb h=new OfflineDb(c);ContentValues v=new ContentValues();v.put("patientId",p);v.put("gameType",type);v.put("difficulty","moderate");v.put("score",score);v.put("accuracy",acc);v.put("reactionTimeMs",rt);v.put("durationSeconds",dur);v.put("createdAt",System.currentTimeMillis());v.put("synced",0);h.getWritableDatabase().insert("sessions",null,v);h.close();}}
